          class="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-base-200"
          @click="goUp"
          v-if="currentPath !== '.'"
        >
          <i class="fa-solid fa-folder text-warning w-4"></i>
          <span class="text-sm font-mono">..</span>
        </div>

        <!-- Entries: folders and files -->
        <div
          v-for="entry in visibleEntries"
          :key="entry.file_path"
          class="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-base-200 group transition-colors"
          :class="isEntrySelected(entry) && 'bg-blue-100 dark:bg-blue-900'"
          @click="handleEntryClick(entry, $event)"
          @dragstart="onDragStart($event, entry)"
          @dragend="onDragEnd"
          draggable="true"
        >
          <i
            class="w-4 text-sm"
            :class="entry.is_dir ? 'fa-solid fa-folder text-warning' : 'fa-regular fa-file text-info'"
          ></i>
          <span class="text-sm font-mono flex-1 truncate" :title="entry.name">{{ entry.name }}</span>
