<script>
import { DockviewVue } from 'dockview-vue'

const STORAGE_KEY = 'filebrowser-layout'
const AUTO_SAVE_DELAY = 1000

export default {
  name: 'FileExplorerPanel',
  components: {
    DockviewVue
  },
  data() {
    return {
      dockviewApi: null,
      layoutRestored: false,
      autoSaveTimeout: null,
      openFiles: new Map(),
      splitterConfig: {
        left: {
          minSize: 15,
          defaultSize: 25,
          collapsible: true
        },
        right: {
          minSize: 15,
          defaultSize: 75,
          collapsible: true
        }
      }
    }
  },
  computed: {
    panelTabIds() {
      return this.dockviewApi?.panels.map(p => p.id) || []
    }
  },
  methods: {
    handleFileOpen(fileData) {
      // Generate unique tab ID for the file
      const tabId = `file-${fileData.path}-${Date.now()}`

      // Track file locally
      this.openFiles.set(tabId, {
        tabId,
        path: fileData.path,
        name: fileData.name,
        openedAt: new Date()
      })

      // Add panel to dockview
      this.addFilePanel({
        tabId,
        path: fileData.path,
        name: fileData.name
      })
    },
    onReady(event) {
      this.dockviewApi = event.api
      this.restoreLayout()
      this.dockviewApi.onDidAddPanel(this.onAddPanel.bind(this))
      this.dockviewApi.onDidRemovePanel(this.onRemovePanel.bind(this))
      this.dockviewApi.onDidLayoutChange(this.onLayoutChange.bind(this))
    },
    addFilePanel(file) {
      if (!file?.tabId) return
      try {
        this.addPanel({
          id: file.tabId,
          title: file.name,
          component: 'file-viewer',
          renderer: 'always',
          params: {
            filePath: file.path,
            fileName: file.name
          }
        })
      } catch (ex) {
        console.error('Error adding file panel:', ex)
      }
    },
    addPanel({ id, title, component, position, params, renderer }) {
      if (!this.dockviewApi) return
      if (!this.dockviewApi.panels.find(p => p.id === id)) {
        this.dockviewApi.addPanel({
          id,
          title,
          component,
          position,
          renderer,
          params: { ...params, tabName: title },
          tabComponent: 'tabComponent'
        })
      }
    },
    onAddPanel() {
      this.debouncedAutoSave()
    },
    onRemovePanel(panel) {
      // Remove file from local tracking
      this.openFiles.delete(panel.id)
      this.debouncedAutoSave()
    },
    onLayoutChange() {
      this.debouncedAutoSave()
    },
    debouncedAutoSave() {
      if (this.autoSaveTimeout) {
        clearTimeout(this.autoSaveTimeout)
      }
      this.autoSaveTimeout = setTimeout(() => {
        this.saveLayout()
      }, AUTO_SAVE_DELAY)
    },
    saveLayout() {
      if (!this.dockviewApi) return null
      const layout = this.dockviewApi.toJSON()
      localStorage.setItem(STORAGE_KEY, JSON.stringify(layout))
      return layout
    },
    restoreLayout(layout = null) {
      if (this.layoutRestored) return true
      if (!this.dockviewApi) return false
      try {
        const data = layout || JSON.parse(localStorage.getItem(STORAGE_KEY))
        if (!data) return false
        this.dockviewApi.fromJSON(data)
        this.layoutRestored = true
      } catch (e) {
        console.warn('Failed to restore file browser layout:', e)
        return false
      }
    }
  }
}
</script>

